WITH base AS (SELECT *, FLOOR(shipping_fee) AS shipping_fee_whole, COALESCE(discount, 0) AS discount_filled FROM orders WHERE order_date >= DATE '2023-08-19'), metrics AS (SELECT *, LAG(shipping_fee, 2) OVER (ORDER BY discount_filled, id) AS prev_shipping_fee, ROW_NUMBER() OVER (PARTITION BY status, store_id ORDER BY shipping_fee DESC, id) AS event_seq, AVG(discount) OVER (PARTITION BY channel ORDER BY shipping_fee, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS discount_avg_5, NTILE(5) OVER (ORDER BY amount, id) AS amount_bucket, AVG(discount) OVER (PARTITION BY channel ORDER BY shipping_fee, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS discount_avg_3 FROM base), scored AS (SELECT *, LAG(discount, 2, 0) OVER (PARTITION BY store_id ORDER BY shipping_fee, id) AS prev_discount, ROW_NUMBER() OVER w_part AS seq_no, SUM(discount_filled) OVER (ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_filled, ROW_NUMBER() OVER w_running AS row_seq, AVG(discount_avg_3) OVER w_part_2 AS discount_avg_3_avg_3 FROM metrics WINDOW w_part AS (PARTITION BY MONTH(order_date), channel ORDER BY order_date DESC, id), w_running AS (PARTITION BY channel ORDER BY discount_avg_5 DESC, id), w_part_2 AS (PARTITION BY channel, store_id ORDER BY discount_avg_5, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), with_windows AS (SELECT id, customer_id, order_date, status, channel, amount, shipping_fee, shipping_fee_whole, prev_shipping_fee, discount_avg_5, amount_bucket, discount_avg_3, seq_no, row_seq, discount_avg_3_avg_3, LAST_VALUE(discount_avg_3_avg_3) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY amount_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_discount_avg_3_avg_3, LAG(seq_no, 1, 0) OVER (PARTITION BY customer_id ORDER BY prev_discount, id) AS prev_seq_no FROM scored), filtered AS (SELECT id, customer_id, order_date, status, channel, amount, shipping_fee, shipping_fee_whole, prev_shipping_fee, discount_avg_5, discount_avg_3, seq_no, row_seq, discount_avg_3_avg_3, prev_seq_no, COALESCE(row_seq, 0) AS row_seq_filled FROM with_windows WHERE status IN ('CANCELLED', 'PENDING')), deduped AS (SELECT * FROM filtered QUALIFY RANK() OVER (PARTITION BY channel, status ORDER BY discount_avg_3 DESC) = 1) SELECT customer_id, DATE_TRUNC('YEAR', order_date) AS year_start, COUNT(*) AS cnt, MAX(shipping_fee_whole) AS max_shipping_fee_whole, COUNT(*) FILTER (WHERE status = 'SHIPPED') AS shipped_rows FROM deduped GROUP BY 1, 2 HAVING COUNT(*) > 1;
